/**
 * dsh-file-workbench — 浏览器入口（DSH 客户端模块格式，esbuild → lib/client.js）。
 *
 * 不注册任何会话插槽：直接以原生 DOM 把 Vue 文件工作台（顶部下拉抽屉）挂到
 * document.body。交互仿安卓通知栏 —— 顶部常驻把手，点击/下拉展开工作台，
 * 点顶部 grip / 上滑收起。
 */
import { zh, en } from "../shared/locales.js";
import type {
  ChatSearchHit,
  MainConversationSnapshot,
  MainConversationTurn,
  MainConversationTool,
  MainConvResult,
  MainConversationMessage,
  SessionSearchHit,
  SessionSearchResult,
} from "../shared/types.js";

/** 前端资源基址（host REST + 静态资源前缀）。 */
export const PREFIX = "/api/dsh-file-workbench";

/** 此插件的 apply 依赖的客户端服务。 */
export const inject = ["locale", "sessions", "workspaces"];

/** 翻译字典注册到 DSH locale registry 的命名空间。 */
const LOCALE_NS = "dsh-file-workbench";

/** 抽屉宿主元素 id（全局唯一，避免重复 apply 时重建）。 */
const HOST_ID = "dsh-file-workbench-shell";

/** Vue 运行时桥接在 window 上的形状（与 src/vue/main.ts 注册的字段保持一致）。 */
interface WorkbenchBridge {
  apiBase: string;
  pickDirectory?: () => Promise<string | null>;
  getSessionDir: () => string | null;
  getSessionId: () => string | null;
  syncSessionWorkspace?: () => void;
  pendingOpens?: { kind: "file" | "folder"; path: string }[];
  getMainConversation?: () => Promise<MainConversationSnapshot>;
  subscribeMainConversation?: (cb: () => void) => () => void;
  /** 订阅当前选中的会话 id 变化（会话切换时回调最新 id，供 SSE 重连）。返回注销函数。 */
  subscribeCurrentSessionId?: (cb: (id: string | null) => void) => () => void;
  sendMainConversation?: (msg: MainConversationMessage) => Promise<MainConvResult>;
  stopMainConversation?: () => Promise<MainConvResult>;
  searchSessions?: (query: string) => Promise<SessionSearchResult>;
  openSession?: (id: string) => Promise<MainConvResult>;
  locale: unknown;
  openExternalFile?: (path: string) => void;
  openExternalFolder?: (path: string) => void;
}

/** 会话事件流上的一条折叠记录（宽松取用 event 字段）。 */
interface SessionEventRecord {
  event?: SessionEvent;
}

/** 足够读取工具调用参数的最小会话事件形状。 */
interface SessionEvent {
  type?: string;
  data?: any;
}

/** ctx.sessions.list 快照的最小形状（current=当前选中 id；byId=各会话元信息）。 */
interface SessionList {
  current?: string;
  byId?: Record<string, { cwd?: string }>;
}

interface ClientCtx {
  effect(fn: () => unknown, label: string): unknown;
  locale: {
    register(namespace: string, lang: string, dict: Record<string, string>): () => void;
  };
  workspaces?: {
    pickDirectory?: () => Promise<string | null>;
    /** 会话侧打开文件的唯一门户：包装它以把聊天中的文件打开改道到工作台预览。 */
    openPath?: (path: string) => Promise<void>;
  };
  sessions?: {
    list: {
      getSnapshot(): SessionList;
      subscribe?(cb: () => void): () => void;
    };
    /** 在会话对象层解析绑定（含 eventSource 事件流）。 */
    binding?(id: string): { session?: MainSessionFace } | undefined;
    manager?: {
      get?(id: string): MainSessionFace | undefined;
    };
    /** 跨会话消息正文检索（宿主维护的可见内容索引，结果请求局部）。 */
    search?(query: string, signal: AbortSignal): Promise<SessionSearchRpc>;
    /** 把指定会话切换为当前会话（列表快照驱动 UI 联动）。 */
    open?(id: string): void;
  };
}

/** ctx.sessions.search 的宽松返回形状（RpcResult<{ items; hasMore }>）。 */
interface SessionSearchRpc {
  ok: boolean;
  value?: { items?: { sessionId?: string; snippet?: string }[]; hasMore?: boolean };
  error?: { message?: string };
}

/**
 * 主会话（SessionFace）最小形状：行为动词 + 对话 ObservableSnapshot 读侧。
 * 与宿主 build 结构对齐，防御性访问（可缺省）以容忍宿主版本差异。
 */
interface MainSessionFace {
  open?: () => Promise<void>;
  eventSource?: { getSnapshot(): { entries: SessionEventRecord[] } };
  prompt?: (
    content: unknown[],
    mode: string,
    signal?: AbortSignal,
  ) => Promise<{ accepted?: boolean; error?: unknown } | undefined>;
  cancel?: () => Promise<unknown>;
  getSnapshot?: () => MainConversationRaw | undefined;
  subscribe?: (cb: () => void) => void;
}

/** DSH ConversationSnapshot 的最小结构（归一化用）。 */
interface MainConvNodeRaw {
  kind?: string;
  seq?: number;
  time?: number;
  content?: unknown[];
  blocks?: { kind?: string; text?: string; name?: string; callId?: string; argsRaw?: string; arguments?: unknown }[];
  messageId?: string;
  interrupted?: true;
  name?: string;
  args?: string;
  text?: string;
  message?: string;
  isError?: boolean;
  error?: { name?: string; code?: string };
  callId?: string;
  call?: { name?: string; argsRaw?: string };
}
interface MainConversationRaw {
  sessionId?: string;
  nodes?: MainConvNodeRaw[];
  partial?: { blocks?: { kind?: string; text?: string; name?: string; callId?: string; argsRaw?: string }[] } | null;
  running?: boolean;
  runningCalls?: { callId?: string; name?: string; argsRaw?: string }[];
  promptError?: { error?: { message?: string } } | null;
  lastAgentError?: string | null;
  blank?: boolean;
  hasMore?: boolean;
}

export function apply(ctx: ClientCtx): void {
  const apiBase = `${window.location.origin}${PREFIX}`;

  // 尽力获取宿主的目录选择能力（workspaces 服务可能未注入，缺省时 Vue 走路径输入框）。
  let pickDirectory: (() => Promise<string | null>) | undefined;
  try {
    pickDirectory = ctx.workspaces?.pickDirectory;
  } catch {
    /* workspaces 服务不可用，忽略 */
  }

  // 读取当前会话（对话）的工作目录；sessions 服务不可得时缺省返回 null。
  const getSessionDir = (): string | null => {
    try {
      const list = ctx.sessions?.list?.getSnapshot?.();
      const id = list?.current;
      return (id && list?.byId?.[id]?.cwd) || null;
    } catch {
      return null;
    }
  };

  // 读取当前（选中的）会话 id，供子 agent 委派作为父级（继承其 standard 组装）。
  const getSessionId = (): string | null => {
    try {
      return ctx.sessions?.list?.getSnapshot?.()?.current ?? null;
    } catch {
      return null;
    }
  };

  // 会话触碰文件与运行态不再在此收集：统一由后端 /stream/session SSE 实时推送
  // （前端只需上报当前选中的会话 id，见 subscribeCurrentSessionId）。

  // ---- 主会话（主页那个会话）对话的桥接：发送/停止/读取/订阅 ----
  // 解析当前会话的 SessionFace（行为动词 + ObservableSnapshot 读侧）。
  const resolveMainSession = (): MainSessionFace | undefined => {
    try {
      const id = getSessionId();
      if (!id) return undefined;
      return ctx.sessions?.binding?.(id)?.session ?? ctx.sessions?.manager?.get?.(id);
    } catch {
      return undefined;
    }
  };

  const EMPTY_CONV = (): MainConversationSnapshot => ({
    sessionId: "",
    blank: true,
    hasMore: false,
    running: false,
    partialText: "",
    partialReasoning: "",
    error: null,
    turns: [],
  });

  /** 从任意内容块里尽量提取纯文本（防御性）。 */
  const blockText = (b: unknown): string => {
    if (typeof b === "string") return b;
    if (!b || typeof b !== "object") return "";
    const rec = b as Record<string, unknown>;
    if (typeof rec.text === "string") return rec.text;
    if (typeof rec.content === "string") return rec.content;
    return "";
  };
  const contentText = (content: unknown[] | undefined): string => {
    if (!Array.isArray(content)) return "";
    return content.map(blockText).join("");
  };

  /** 把 DSH ConversationSnapshot 归一化为纯 JSON 渲染模型（按 seq 顺序）。 */
  const normalizeConversation = (snap: MainConversationRaw | undefined): MainConversationSnapshot => {
    if (!snap) return EMPTY_CONV();
    const turns: MainConversationTurn[] = [];
    const nodes = Array.isArray(snap.nodes) ? snap.nodes : [];
    for (const n of nodes) {
      if (!n || typeof n !== "object") continue;
      const kind = n.kind ?? "";
      const time = typeof n.time === "number" ? n.time : Date.now();
      const id = String(n.seq ?? n.callId ?? n.messageId ?? `t${turns.length}`);
      if (kind === "user") {
        turns.push({ id, role: "user", text: contentText(n.content), time });
      } else if (kind === "assistant") {
        const parts: string[] = [];
        const reasoning: string[] = [];
        const tools: MainConversationTool[] = [];
        for (const b of n.blocks ?? []) {
          if (!b || typeof b !== "object") continue;
          if (b.kind === "reasoning") reasoning.push(b.text ?? "");
          else if (b.kind === "tool-call") tools.push({ name: b.name ?? "", args: b.argsRaw ?? "" });
          else if (b.kind === "text") parts.push(b.text ?? "");
        }
        turns.push({
          id,
          role: "assistant",
          text: parts.join(""),
          reasoning: reasoning.join(""),
          tools: tools.length ? tools : undefined,
          time,
          interrupted: n.interrupted === true,
        });
      } else if (kind === "tool-result") {
        const name = n.call?.name ?? n.name ?? "";
        turns.push({
          id,
          role: "tool",
          text: name,
          tools: [
            {
              name,
              args: n.call?.argsRaw ?? "",
              isError: n.isError === true,
              error: n.error?.name ?? "",
            },
          ],
          time,
        });
      } else if (kind === "steering" || kind === "context") {
        turns.push({ id, role: "system", text: contentText(n.content), time });
      } else if (kind === "command") {
        const cmd = `/${(n.name ?? "")} ${(n.args ?? "")}`.trim();
        turns.push({ id, role: "system", text: cmd || "命令", time });
      } else if (kind === "turn-error") {
        turns.push({ id, role: "system", text: n.message ?? "回合出错", time });
      } else {
        // model-retry / compaction / turn-max-tokens / unknown：仅占位系统行
        turns.push({ id, role: "system", text: "", time });
      }
    }

    // 进行中的工具调用（tool/call 已见、tool/result 未回）追加为工具卡。
    for (const c of Array.isArray(snap.runningCalls) ? snap.runningCalls : []) {
      if (!c || typeof c !== "object") continue;
      turns.push({
        id: c.callId ?? `run${turns.length}`,
        role: "tool",
        text: c.name ?? "",
        tools: [{ name: c.name ?? "", args: c.argsRaw ?? "" }],
        time: Date.now(),
      });
    }

    // 进行中助手输出的累积文本/思考。
    let partialText = "";
    let partialReasoning = "";
    for (const b of snap.partial?.blocks ?? []) {
      if (!b || typeof b !== "object") continue;
      if (b.kind === "reasoning") partialReasoning += b.text ?? "";
      else if (b.kind === "text") partialText += b.text ?? "";
      else if (b.kind === "tool-call") partialText += `\n🛠 调用工具 ${b.name ?? ""}…`;
    }

    const perror = snap.promptError?.error;
    const error = snap.lastAgentError ?? (perror ? perror.message ?? "发送/停止失败" : null);
    return {
      sessionId: snap.sessionId ?? "",
      blank: snap.blank === true,
      hasMore: snap.hasMore === true,
      running: snap.running === true,
      partialText,
      partialReasoning,
      error,
      turns,
    };
  };

  /** 读取当前主会话对话的归一化镜像。 */
  const getMainConversation = async (): Promise<MainConversationSnapshot> => {
    const session = resolveMainSession();
    if (!session?.getSnapshot) return EMPTY_CONV();
    try {
      await session.open?.();
    } catch {
      /* 打开历史失败不阻塞 */
    }
    try {
      return normalizeConversation(session.getSnapshot());
    } catch {
      return EMPTY_CONV();
    }
  };

  /** 向当前主会话发送一条消息（同主页 entrance，mode=queue；支持文本 + 图片附件）。 */
  const sendMainConversation = async (msg: MainConversationMessage): Promise<MainConvResult> => {
    const session = resolveMainSession();
    if (!session?.prompt) return { ok: false, error: "主会话不可用：请先进入一个聊天会话。" };
    // 组装 content blocks：文本 + 可选图片（图片以 base64 传给 host，由 DSH 侧做附件持久化）。
    const content: Array<{ type: "text"; text: string } | { type: "image"; mediaType: string; data: string; name?: string }> = [];
    const text = (msg.text ?? "").trim();
    if (text) content.push({ type: "text", text });
    for (const img of msg.images ?? []) {
      if (!img || typeof img.data !== "string" || !img.data) continue;
      content.push({
        type: "image",
        mediaType: img.mediaType || "image/png",
        data: img.data,
        name: img.name,
      });
    }
    if (content.length === 0) return { ok: false, error: "消息内容为空。" };
    try {
      await session.open?.();
      const r = await session.prompt(content, "queue");
      const rawError =
        r && r.error !== undefined
          ? String((r.error as { message?: unknown })?.message ?? r.error)
          : undefined;
      return r?.accepted === true
        ? { ok: true }
        : { ok: false, error: rawError ?? "会话未接受该消息，请重试。" };
    } catch (e) {
      return { ok: false, error: (e as Error)?.message ?? String(e) };
    }
  };

  /** 停止当前主会话正在进行的回合（cancel）。 */
  const stopMainConversation = async (): Promise<MainConvResult> => {
    const session = resolveMainSession();
    if (!session?.cancel) return { ok: false, error: "主会话不可用：无法停止。" };
    try {
      await session.open?.();
      await session.cancel();
      return { ok: true };
    } catch (e) {
      return { ok: false, error: (e as Error)?.message ?? String(e) };
    }
  };

  /** 跨会话消息正文检索（DSH sessions.search；结果请求局部，不改变当前会话选中）。
   *  若当前 DSH 部署未开放会话索引（openAt:"never"，sessions.search 抛错/空），
   *  回退为本地扫描各会话 cwd 做文件内容/名称搜索（走工作台后端 chat-search）。 */
  const searchSessions = async (query: string): Promise<SessionSearchResult> => {
    const q = (query ?? "").trim();
    if (!q) return { items: [], hasMore: false };
    // 优先 DSH 会话全文索引
    try {
      const r = await ctx.sessions?.search?.(q, new AbortController().signal);
      if (r?.ok && r.value && (r.value.items ?? []).length > 0) {
        const items = (r.value.items ?? [])
          .map((it) => ({ sessionId: String(it.sessionId ?? ""), snippet: it.snippet ?? "" }))
          .filter((it) => it.sessionId);
        return { items, hasMore: r.value.hasMore === true };
      }
    } catch {
      /* 会话索引未开放 → 走本地文件回退 */
    }
    // 本地回退：枚举会话目录 → 后端批量搜索文件内容/名称
    try {
      const list = ctx.sessions?.list?.getSnapshot?.();
      const byId = list?.byId ?? {};
      const norm = (p: string): string => String(p || "").replace(/[\\/]+$/, "");
      const dirToId = new Map<string, string>();
      for (const [id, meta] of Object.entries(byId)) {
        if (meta && typeof meta === "object" && (meta as { cwd?: string }).cwd) {
          dirToId.set(norm((meta as { cwd: string }).cwd).toLowerCase(), id);
        }
      }
      const dirs = [...dirToId.values()].length ? [...new Set(dirToId.keys())].map((d) => d.toLowerCase()).filter((d) => d) : [];
      const res = await fetch(`${PREFIX}/chat-search`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ dirs, q }),
      });
      const data = res.ok ? ((await res.json()) as { data?: { hits?: ChatSearchHit[]; truncated?: boolean } }) : undefined;
      const hits: SessionSearchHit[] = [];
      for (const h of data?.data?.hits ?? []) {
        // 文件命中：按 dir 反查会话 id；消息命中：后端已带 sessionId（转写目录名即会话 id）。
        const sessionId = h.sessionId || (h.dir ? dirToId.get(norm(h.dir).toLowerCase()) : undefined);
        if (!sessionId) continue;
        if (h.kind === "message") {
          hits.push({
            sessionId,
            snippet: h.snippet ?? "",
            messageText: h.messagePreview,
            message: true,
            byContent: true,
          });
        } else {
          hits.push({
            sessionId,
            snippet: h.snippet || h.name || "",
            file: h.path,
            name: h.name,
            byContent: h.byContent,
          });
        }
      }
      return { items: hits, hasMore: !!data?.data?.truncated };
    } catch {
      return { items: [], hasMore: false };
    }
  };

  /** 把指定 DSH 会话切换为当前会话（open；列表快照更新后主会话镜像自动重订）。 */
  const openSession = async (id: string): Promise<MainConvResult> => {
    if (!id) return { ok: false, error: "会话不存在。" };
    try {
      ctx.sessions?.open?.(id);
      return { ok: true };
    } catch (e) {
      return { ok: false, error: (e as Error)?.message ?? String(e) };
    }
  };

  /**
   * 订阅当前主会话对话变化。随 `ctx.sessions.list` 切换自动重订子订阅，
   * 返回组合注销函数（注销对会话内订阅与列表切换订阅）。
   */
  const subscribeMainConversation = (cb: () => void): (() => void) => {
    const innerDisposes: Array<() => void> = [];
    let disposed = false;
    const bind = (): void => {
      for (const off of innerDisposes) {
        try {
          off();
        } catch {
          /* ignore */
        }
      }
      innerDisposes.length = 0;
      const session = resolveMainSession();
      if (!session?.subscribe) return;
      const ret = session.subscribe(cb);
      if (typeof ret === "function") innerDisposes.push(ret);
    };
    const unsubList = ctx.sessions?.list?.subscribe?.(() => {
      if (disposed) return;
      bind();
      try {
        cb();
      } catch {
        /* ignore */
      }
    });
    bind();
    return () => {
      disposed = true;
      for (const off of innerDisposes) {
        try {
          off();
        } catch {
          /* ignore */
        }
      }
      innerDisposes.length = 0;
      try {
        unsubList?.();
      } catch {
        /* ignore */
      }
    };
  };

  /**
   * 订阅当前选中的会话 id 变化。随 `ctx.sessions.list` 的 current 切换回调最新 id；
   * 无选中会话时回调 null（供 Vue 侧断开 SSE）。后端 /stream/session 负责据此推送
   * 该会话触碰文件与运行态，前端无需轮询。
   */
  const subscribeCurrentSessionId = (cb: (id: string | null) => void): (() => void) => {
    let disposed = false;
    const notify = (): void => {
      if (disposed) return;
      try {
        cb(getSessionId());
      } catch {
        /* ignore */
      }
    };
    const unsubList = ctx.sessions?.list?.subscribe?.(notify);
    notify(); // 建初始基线
    return () => {
      disposed = true;
      try {
        unsubList?.();
      } catch {
        /* ignore */
      }
    };
  };

  // 预置 Vue 运行时的注入点（apiBase + 目录选择 + 会话目录 + 会话文件 + 主会话对话 + locale 服务），供 Vue useApi /「打开文件夹」/ useI18n 读取。
  (window as unknown as { __DSH_FILE_WORKBENCH__?: WorkbenchBridge }).__DSH_FILE_WORKBENCH__ = {
    apiBase,
    pickDirectory,
    getSessionDir,
    getSessionId,
    getMainConversation,
    subscribeMainConversation,
    subscribeCurrentSessionId,
    sendMainConversation,
    stopMainConversation,
    searchSessions,
    openSession,
    locale: ctx.locale,
  };

  // ---- 监听当前（选中）会话的切换：变更时通知工作台 进入其工作区/仅刷新文件夹 ----
  let lastSessionId: string | null = getSessionId();
  let lastSessionDir: string | null = getSessionDir();
  const onSessionsChange = (): void => {
    const next = getSessionId();
    const nextDir = getSessionDir();
    const g = (window as unknown as { __DSH_FILE_WORKBENCH__?: WorkbenchBridge }).__DSH_FILE_WORKBENCH__;
    if (!next) return;
    const dirChanged = nextDir !== lastSessionDir;
    lastSessionDir = nextDir;
    if (next !== lastSessionId) {
      lastSessionId = next;
      // 切到新会话：进入其工作区。
      g?.syncSessionWorkspace?.();
      return;
    }
    // 同一会话内工作目录（cwd）变化：工作台默认工作区跟随联动。
    if (dirChanged) g?.syncSessionWorkspace?.();
  };
  const unsubSessions = ctx.sessions?.list?.subscribe?.(onSessionsChange) ?? null;
  if (unsubSessions) {
    ctx.effect(() => unsubSessions, "dsh-file-workbench: session-switch watch");
  }

  // ---- 通道一：拦截 ctx.workspaces.openPath，把会话侧文件打开改道到工作台 ----
  // host 客户端里所有"会话打开文件"（工具行路径、produced-files 产物行、正文提及）最终都调
  // 用 ctx.workspaces.openPath。包装该方法：工作台已挂载时把打开请求交给 Vue 端（openPreview /
  // 资源管理器），不再落入宿主 OS；未挂载时回落到原方法。
  const routeOpen = (kind: "file" | "folder", path: string): void => {
    const g = (window as unknown as { __DSH_FILE_WORKBENCH__?: WorkbenchBridge }).__DSH_FILE_WORKBENCH__;
    if (!g) return;
    const fn = kind === "file" ? g.openExternalFile : g.openExternalFolder;
    if (fn) fn(path);
    else (g.pendingOpens = g.pendingOpens ?? []).push({ kind, path });
  };

  const ws = ctx.workspaces;
  // 手动点击接管（best-effort）：部分宿主 build 会让会话内文件打开走 ctx.workspaces.openPath，
  // 此时把打开改道人到工作台预览；宿主不提供该方法（本环境实测如此）时静默跳过、不影响其它能力。
  if (ws && typeof ws.openPath === "function") {
    const original = ws.openPath.bind(ws);
    ws.openPath = (path: string): Promise<void> => {
      // 工作台未挂载（或已卸载）时不接管，交由宿主打开。
      if (!document.getElementById(HOST_ID)) return original(path);
      // "Show in folder" 揭示手势（路径以 . 结尾）：改道人到工作台资源管理器。
      const trimmed = path.replace(/[\\/]+$/, "");
      const isReveal = path === "." || path === "./" || trimmed === "." || /[\\/]\.$/.test(trimmed);
      if (isReveal) {
        const dir = getSessionDir();
        if (dir) {
          routeOpen("folder", dir);
          return Promise.resolve();
        }
        return original(path);
      }
      // 普通文件打开：改道人到工作台预览。
      routeOpen("file", path);
      return Promise.resolve();
    };
  }

  // 注册 zh/en 字典到 DSH locale registry，使抽屉标题按语言取词。
  ctx.effect(() => {
    const offZh = ctx.locale.register(LOCALE_NS, "zh", zh as Record<string, string>);
    const offEn = ctx.locale.register(LOCALE_NS, "en", en as Record<string, string>);
    return () => {
      offZh();
      offEn();
    };
  }, "dsh-file-workbench: dictionaries");

  // 已挂载过则复用，防重复 apply 重复注入/重建。
  if (document.getElementById(HOST_ID)) return;

  // 宿主容器：固定覆盖视口，不拦截下层页面事件；内部抽屉/把手自行开启 pointer-events。
  const host = document.createElement("div");
  host.id = HOST_ID;
  host.style.cssText = "position:fixed;inset:0;pointer-events:none;z-index:2147483000;";
  document.body.appendChild(host);

  // 注入 Vue 产物样式与模块脚本；模块加载完成后挂载到 host。
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = `${apiBase}/${__VUE_CSS__}`;
  document.head.appendChild(link);

  const script = document.createElement("script");
  script.type = "module";
  script.src = `${apiBase}/${__VUE_ENTRY__}`;
  document.head.appendChild(script);

  let attempts = 0;
  let mounted = false;
  const poll = window.setInterval(() => {
    if (mounted) return;
    const mfn = (window as unknown as { __dshFileWorkbenchMount__?: (el: HTMLElement) => void }).__dshFileWorkbenchMount__;
    if (typeof mfn === "function" && document.getElementById(HOST_ID)) {
      mounted = true;
      window.clearInterval(poll);
      mfn(host);
    } else if (++attempts > 300) {
      window.clearInterval(poll);
    }
  }, 50);
}